"action" value="reset_staff_password"><input type="hidden" name="user_id" value="<?=(int)$u['user_id']?>"><button class="secondary small">Reset staff password</button></form><?php endif;?><?php else:?>Active<?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
